-- Generated by `npm run db:schema` from a database built from supabase/migrations. Do not edit: change a migration.

CREATE OR REPLACE FUNCTION public.saved_listing_page(p_query text DEFAULT NULL::text, p_sort text DEFAULT 'newest'::text, p_limit integer DEFAULT 24, p_offset integer DEFAULT 0)
 RETURNS TABLE(listing_id uuid, total integer)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  with mine as (
    select l.id, l.created_at, l.price_cents
    from public.saves s
    join public.listings l on l.id = s.target_id
    where s.user_id = auth.uid() and s.target_type = 'listing'
      and (nullif(btrim(coalesce(p_query, '')), '') is null
           or l.title ilike '%' || replace(replace(replace(btrim(p_query), '\', '\\'), '%', '\%'), '_', '\_') || '%')
  )
  select m.id, (count(*) over ())::integer
  from mine m
  order by
    case when p_sort = 'price' then m.price_cents end asc,
    case when p_sort = 'price' then m.id end asc,
    m.created_at desc,
    m.id desc
  offset greatest(coalesce(p_offset, 0), 0)
  limit least(greatest(coalesce(p_limit, 24), 1), 100);
$function$;

comment on function public.saved_listing_page(p_query text, p_sort text, p_limit integer, p_offset integer) is 'One page of the caller''s saved parts they can still see, by title search, newest or price, with the total (N31).';

grant execute on function public.saved_listing_page(p_query text, p_sort text, p_limit integer, p_offset integer) to authenticated;
